fn fibonacci(n: usize) -> Vec<i32> {
    // Since n ≥ 2 (as per problem statement), initialize vector with capacity n
    let mut fib = Vec::with_capacity(n);
    
    // Base cases:
    fib.push(0); // F(0) = 0
    fib.push(1); // F(1) = 1
    
    // Compute Fibonacci numbers from 2 to n-1
    for i in 2..n {
        // Each Fibonacci number fits in i32 by assumption, so no overflow expected.
        let next = fib[i - 1] + fib[i - 2];
        fib.push(next);
    }
    
    fib
}